const bottomMetricLabels = new Set(["Sack Rate Allowed","Havoc Allowed","Turnovers"]);
const footballMetricOrder=['EPA / Play','Success Rate','Explosiveness','Rush Rate','Pass Rate','Passing Success Rate','Rushing Success Rate','Sack Rate Allowed','Havoc Allowed','Turnovers','Third Down Conversion','Points per Opportunity','Red Zone TD Rate'];
const orderMetrics=metrics=>[...metrics].sort((a,b)=>(footballMetricOrder.indexOf(a.label)<0?999:footballMetricOrder.indexOf(a.label))-(footballMetricOrder.indexOf(b.label)<0?999:footballMetricOrder.indexOf(b.label)));
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let dashboard,selectedGame,activeDay="all";
const hexRgb=h=>{const x=String(h||"").replace("#","");if(!/^[0-9a-f]{6}$/i.test(x))return null;return [0,2,4].map(i=>parseInt(x.slice(i,i+2),16))};
const isDark=h=>{const rgb=hexRgb(h);if(!rgb)return false;const [r,g,b]=rgb.map(v=>v/255);const lin=[r,g,b].map(v=>v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*lin[0]+.7152*lin[1]+.0722*lin[2]<.16};
const luminance=h=>{const rgb=hexRgb(h);if(!rgb)return 0;const [r,g,b]=rgb.map(v=>v/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*r+.7152*g+.0722*b};
const color=(t,i)=>{const bg=luminance("#181d1a");const options=[t.color,t.alternate_color,t.secondary_color].filter(h=>!!hexRgb(h)).map(h=>({h,l:luminance(h)})).map(x=>({...x,contrast:(Math.max(x.l,bg)+.05)/(Math.min(x.l,bg)+.05)})).sort((a,b)=>b.contrast-a.contrast);return options[0]?.contrast>=4.5?options[0].h:"#ffffff"};
const logo=t=>t.alternate_logo&&isDark(t.color)?t.alternate_logo:(t.logo||t.alternate_logo||"");
const abbr=t=>t.abbr||t.name.split(/\\s+/).map(x=>x[0]).join("").slice(0,4).toUpperCase();
const teamLogo=(t,cls="team-logo")=>{const src=logo(t),initials=`<span class="${cls} logo-fallback" aria-label="${esc(t.name)}">${esc(abbr(t))}</span>`;if(!src)return initials;const secondary=t.alternate_logo&&src!==t.alternate_logo?t.alternate_logo:"";return `<span class="team-logo-wrap"><img class="${cls}" src="${esc(src)}" alt="${esc(t.name)} logo" loading="lazy" onerror="if(this.dataset.secondary){this.src=this.dataset.secondary;this.dataset.secondary=''}else{this.hidden=true;this.nextElementSibling.hidden=false}" data-secondary="${esc(secondary)}"><span class="${cls} logo-fallback" hidden>${esc(abbr(t))}</span></span>`};
const rank=v=>v==null?"—":`#${Number(v)}`;
const rawVal=(v,fmt)=>{if(v==null)return"—";const n=Number(v);if(!Number.isFinite(n))return"—";if(fmt==="percent")return (n*100).toFixed(1)+"%";if(fmt==="decimal")return n.toFixed(3);return String(v)};
const kickoff=g=>{if(!g.kickoff)return "Kickoff TBD";const d=new Date(g.kickoff);return new Intl.DateTimeFormat("en-US",{weekday:"short",hour:"numeric",minute:"2-digit",timeZone:"America/New_York",timeZoneName:"short"}).format(d)};
const spreadLabel=g=>{if(g.market?.spread===null||g.market?.spread===undefined||g.market?.spread==="")return "—";const s=Number(g.market.spread);if(!Number.isFinite(s))return "—";if(s===0)return "PK";const team=s<0?abbr(g.home):abbr(g.away);return `${team} -${Math.abs(s)}`};
const HELP={
"Rush Rate":"Share of offensive plays classified as runs by CollegeFootballData, excluding garbage time. Other play classifications can keep Rush Rate + Pass Rate below 100%. Frequency rank: #1 is the highest share, not best.",
"Pass Rate":"Share of offensive plays classified as passes by CollegeFootballData, excluding garbage time. Other play classifications can keep Rush Rate + Pass Rate below 100%. Frequency rank: #1 is the highest share, not best.",
"Rush Rate Against":"Share of opponent plays classified as runs by CollegeFootballData, excluding garbage time. Other play classifications can keep Rush Rate + Pass Rate below 100%. Frequency rank: #1 is the highest share, not best.",
"Pass Rate Against":"Share of opponent plays classified as passes by CollegeFootballData, excluding garbage time. Other play classifications can keep Rush Rate + Pass Rate below 100%. Frequency rank: #1 is the highest share, not best.",
"Sack Rate Allowed":"Sacks allowed divided by pass attempts plus sacks allowed. Lower is better.",
"Sack Rate":"Defensive sacks divided by opponent pass attempts plus sacks. Higher is better.",
"Havoc Allowed":"CFBD season havoc events allowed per offensive play: tackles for loss, passes defended and forced fumbles. Lower is better.",
"Havoc":"CFBD season havoc events created per opponent play: tackles for loss, passes defended and forced fumbles. Higher is better.",
"Turnovers":"Season giveaways (interceptions and lost fumbles) from official team box scores. Lower is better.",
"Turnovers Forced":"Season takeaways (opponent interceptions and lost fumbles) from official team box scores. Higher is better.",
"Success Rate":"Percentage of offensive plays considered successful by down and distance. Higher is better.",
"Defensive Success Rate":"Percentage of opponent plays considered successful by down and distance. Lower is better.",
"EPA / Play":"Average expected points added per offensive play. Higher is better.",
"EPA / Play Allowed":"Average expected points added by opponents per play. Lower is better.",
"Passing Success Rate":"Percentage of passing plays considered successful. Higher is better.",
"Defensive Pass Success Rate":"Percentage of opponent passing plays considered successful. Lower is better.",
"Rushing Success Rate":"Percentage of rushing plays considered successful. Higher is better.",
"Defensive Rush Success Rate":"Percentage of opponent rushing plays considered successful. Lower is better.",
"Explosiveness":"Average EPA generated on successful offensive plays. Higher means successful plays are more damaging.",
"Explosiveness Allowed":"Average EPA allowed on opponents' successful plays. Lower is better.",
"Points per Opportunity":"Average points scored after creating a scoring opportunity. Higher is better.",
"Points per Opportunity Allowed":"Average points allowed after opponents create scoring opportunities. Lower is better.",
"Third Down Conversion":"Percentage of offensive third downs converted. Higher is better.",
"Third Down Defense":"Percentage of opponent third downs converted. Lower is better.",
"Red Zone TD Rate":"Percentage of red-zone trips that end in touchdowns. Higher is better.",
"Red Zone TD Defense":"Percentage of opponent red-zone trips that end in touchdowns. Lower is better."
};
function seasonMarketRecord(team,type){const row=(selectedGame.market_trends||[]).find(r=>r.label===(type==='ats'?'ATS this season':'O/U this season')||(type==='ou'&&r.label==='Over/under this season'));return row?.[team===selectedGame.away?'away':'home']||'—'}
function season(t,i){const f=t.form||{};return `<article class="season-team" style="--team-color:${color(t,i)}"><div class="season-team-head">${teamLogo(t,"season-team-logo")}<b>${esc(abbr(t))}</b></div><div class="season-stats"><span><strong>${esc(t.record||"—")}</strong><small>Record</small></span><span><strong>${f.avg_points??"—"}</strong><small>PPG</small></span><span><strong>${f.avg_allowed??"—"}</strong><small>PPG Allowed</small></span><span><strong>${esc(seasonMarketRecord(t,"ats"))}</strong><small>Season ATS</small></span><span><strong>${esc(seasonMarketRecord(t,"ou"))}</strong><small>Season O/U</small></span></div></article>`}
function metricCard(m,type){
 const isOff=type==="offense";
 const kicker=isOff?"OFFENSE":"DEFENSE";
 const label=isOff?(m.offense_label||m.label):(m.defense_label||m.label);
 const values=[
   [selectedGame.away,0,isOff?m.away_offense:m.away_defense,isOff?m.away_offense_rank:m.away_defense_rank],
   [selectedGame.home,1,isOff?m.home_offense:m.home_defense,isOff?m.home_offense_rank:m.home_defense_rank]
 ];
 const line=([t,i,v,r])=>`<div class="metric-team" style="--team-color:${color(t,i)};--rank-color:${globalThis.betwiseRankColor?.(t,'cfb')||color(t,i)}"><span class="metric-team-name">${teamLogo(t,"metric-logo")}<b>${esc(abbr(t))}</b></span><span class="metric-number">${rawVal(v,m.format)}</span><span class="metric-rank"><b>${rank(r)}</b><small>FBS rank</small></span><span class="metric-track"><i style="width:${r==null?2:Math.max(2,Math.min(100,100*(1-(Number(r)-1)/Math.max(1,dashboard?.slate?.fbs_count-1||135))))}%"></i></span></div>`;
 return `<article class="metric-card" data-unit="${kicker}"><div class="metric-title"><span><small class="metric-kicker">${kicker} METRIC</small><span class="metric-name">${esc(label)}<button class="info" aria-label="About ${esc(label)}" data-tip="${esc(HELP[label]||"Current-season FBS statistic from CollegeFootballData.")}">?</button></span></span><span class="rank-heading"><i>SEASON STAT</i><b>FBS RANK</b></span></div>${values.map(line).join("")}</article>`
}
function footballMetricCards(metrics){const groups=[['Overall efficiency',['EPA / Play','Success Rate','Explosiveness']],['Passing & rushing',['Rush Rate','Pass Rate','Passing Success Rate','Rushing Success Rate']],['Pressure & possession',['Sack Rate Allowed','Havoc Allowed','Turnovers']],['Scoring opportunities',['Third Down Conversion','Points per Opportunity','Red Zone TD Rate']]];const byLabel=new Map(metrics.map(m=>[m.label,m])),used=new Set();let html='';for(const [category,labels] of groups){const rows=labels.map(label=>byLabel.get(label)).filter(Boolean);if(!rows.length)continue;rows.forEach(m=>used.add(m.label));html+='<h4 class="metric-category">'+esc(category)+'</h4>'+rows.map(pair).join('')}return html+metrics.filter(m=>!used.has(m.label)).map(pair).join('')}
function pair(m){return metricCard(m,"offense")+metricCard(m,"defense")}
function marketTrendRow(t){
 return `<article class="trend-card"><div class="trend-card-head"><strong>${esc(t.label)}</strong><button class="info" data-tip="${esc(t.note||"Current-season betting result.")}" aria-label="About ${esc(t.label)}">?</button></div><div class="trend-values"><span style="--team-color:${color(selectedGame.away,0)}">${teamLogo(selectedGame.away,"trend-logo")}<b>${esc(t.away)}</b></span><i>VS</i><span style="--team-color:${color(selectedGame.home,1)}">${teamLogo(selectedGame.home,"trend-logo")}<b>${esc(t.home)}</b></span></div></article>`;
}
function marketResults(){
 const rows=selectedGame.market_trends||[];
 if(!rows.length)return"";
 return `<section class="trend-group"><div class="trend-group-title"><span>↗</span><h4>Market Results</h4></div><div class="trend-grid">${rows.map(marketTrendRow).join("")}</div></section>`;
}
const usagePct=v=>v==null?"—":`${Math.round((Number(v)<=1?Number(v)*100:Number(v))*10)/10}%`;
function qbEfficiency(player){
 const metric=player.efficiency;
 if(String(player.position||"").toUpperCase()!=="QB" || !metric)return "";
 const value=metric?.value==null?"—":`${Number(metric.value)>=0?"+":""}${Number(metric.value).toFixed(3)}`;
 const rank=metric?.qualified&&metric.rank?`#${metric.rank} / ${metric.qualifying_count}`:"Not qualified";
 return `<div class="qb-efficiency"><div><small>${esc(metric?.label||"Passing PPA")}</small><strong>${value}</strong></div><div><small>QB RANK <button class="info" data-tip="${esc(metric?.help||"Rank appears after the quarterback meets the qualifying sample.")}" aria-label="About QB rank">?</button></small><strong>${rank}</strong></div></div>`;
}

function collegePlayerCard(player,team){
 const items=(player.usage||[]).map(item=>`<div class="usage"><b>${usagePct(item.value)}</b><span>${esc(item.label)}</span></div>`).join("");
 const pos=String(player.position||"").toUpperCase();
 const statLabels=pos==="QB"?["CMP","ATT","PASS YDS","PASS TD","INT","RUSH YDS"]:pos==="RB"?["RUSH","RUSH YDS","RUSH TD","REC","REC YDS","REC TD"]:["REC","REC YDS","REC TD","RUSH","RUSH YDS","RUSH TD"];
 const fields={"CMP":"completions","ATT":"attempts","PASS YDS":"passing_yards","PASS TD":"passing_tds","INT":"interceptions","RUSH":"carries","RUSH YDS":"rushing_yards","RUSH TD":"rushing_tds","REC":"receptions","REC YDS":"receiving_yards","REC TD":"receiving_tds"};
 const production=statLabels.map(label=>{
  const key=fields[label],total=player.production?.totals?.[key],average=player.production?.per_game?.[key];
  const reported=total!==null&&total!==undefined&&Number.isFinite(Number(total));
  return `<span><b>${reported?esc(Number(total).toLocaleString()):"—"}</b><small>${label}</small><em>${reported&&average!==null&&average!==undefined?esc(Number(average).toFixed(1))+" / team game":"Not reported"}</em></span>`;
 }).join("");
 const pending=player.placeholder?`<div class="availability-note"><b>Usage data:</b> Player usage will populate on the next successful season refresh.</div>`:"";
 return `<article class="player-card" style="--team-color:${color(team,team===selectedGame.away?0:1)}"><div class="player-top"><div class="player-identity">${teamLogo(team,"player-team-logo")}<div><span class="position">${esc(player.position||"—")} · ${esc(abbr(team))}</span><h3>${esc(player.name||"Usage data pending")}</h3></div></div><span class="subtle">${esc(player.slot||"Season usage")}</span></div>${pending}${player.availability_note?`<div class="availability-note">${esc(player.availability_note)}</div>`:""}${qbEfficiency(player)}<div class="production-line">${production}</div><div class="usage-label"><b>Opportunity share</b><button class="info" data-tip="Position-specific season opportunity metrics from CFBD. Skill players include Air Yards %; quarterbacks include 3rd Down Completion %." aria-label="About opportunity share">?</button></div><div class="usage-grid">${items||'<div class="usage"><b>—</b><span>Pending</span></div>'}</div></article>`;
}
function playerOpportunity(){
 const players=selectedGame.players||[];
 const half=Math.ceil(players.length/2);
 return `<div class="players">${players.map((player,i)=>collegePlayerCard(player,i<half?selectedGame.away:selectedGame.home)).join("")}</div>`;
}
function formSchedule(){
 const fmt=t=>(t.form?.last_five||[]).map(x=>`${x.result}${x.score?" "+x.score:""}`).join(" · ")||"—";
 const travel=t=>BetWiseDashboardUX.travel(t);
 const rest=t=>{
 const kickoff=selectedGame.kickoff?new Date(selectedGame.kickoff):null;
 if(!kickoff||!Number.isFinite(kickoff.getTime()))return "—";
 const games=(t.form?.last_five||[]).filter(g=>g.start_date&&["W","L","T"].includes(String(g.result||"").toUpperCase()));
 const last=games.map(g=>new Date(g.start_date)).filter(d=>Number.isFinite(d.getTime())&&d<kickoff).sort((a,b)=>b-a)[0];
 if(!last)return "—";
 const dayNumber=d=>{const parts=new Intl.DateTimeFormat("en-US",{timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(d);
 const get=type=>Number(parts.find(p=>p.type===type)?.value);return Date.UTC(get("year"),get("month")-1,get("day"))/86400000};
 const gap=dayNumber(kickoff)-dayNumber(last);
 return gap>=1?String(gap-1)+" days":"—";
};
 const row=(label,a,h,note,seq=false)=>`<article class="context-card${label==="Travel sequence"?" context-card--travel":""}${seq?" context-card--sequence":""}"><strong>${label}</strong><div class="context-sides"><span style="--team-color:${color(selectedGame.away,0)}"><small>${esc(label==="Travel sequence"?BetWiseDashboardUX.opponentCode({opponent_id:selectedGame.away.espn_id,opponent:selectedGame.away.name,opponent_abbr:abbr(selectedGame.away)}):abbr(selectedGame.away))}</small><b>${esc(a)}</b></span><i>VS</i><span style="--team-color:${color(selectedGame.home,1)}"><small>${esc(label==="Travel sequence"?BetWiseDashboardUX.opponentCode({opponent_id:selectedGame.home.espn_id,opponent:selectedGame.home.name,opponent_abbr:abbr(selectedGame.home)}):abbr(selectedGame.home))}</small><b>${esc(h)}</b></span></div><p>${note}</p></article>`;
 return `<section class="context-panel"><div class="context-title"><span>◷</span><div><h4>Form & Schedule</h4><p>Recent results, recovery time and travel context at a glance.</p></div></div><div class="context-grid">${row("Last five games",fmt(selectedGame.away),fmt(selectedGame.home),"Last 5 Results",true)}${row("Rest before kickoff",rest(selectedGame.away),rest(selectedGame.home),"Full calendar days off between the most recent completed game and kickoff, excluding game days.")}${row("Travel sequence",travel(selectedGame.away),travel(selectedGame.home),"Last 5 Game Locations",true)}${row("Game setting",selectedGame.context?.neutral_site?"Neutral": "Road",selectedGame.context?.neutral_site?"Neutral":"Home",selectedGame.context?.conference_game?"Conference matchup.":"Non-conference matchup.")}</div></section>`}
function feature(){
 const f=selectedGame.featured_mismatch;
 if(!f)return "";
 return "";
}

function factorSentence(t){
 const game=selectedGame;
 if(t.type!=="matchup_edge"){
  if(t.type==="bounce_back"){
   const team=[game.away,game.home].find(x=>x.name===t.team);
   const last=team?.form?.last_five?.at(-1);
   return last?.result==="L"?t.team+" lost its last completed game"+(last.opponent?" against "+last.opponent:"")+". Watch whether it improves early-down execution and avoids another slow start.":t.team+" is coming off a loss. Its response in early drives and high-leverage downs is worth watching.";
  }
  if(t.type==="ranked_context")return t.team+" enters with an AP ranking. The ranking provides context, but its execution against this opponent matters more than the label.";
  if(t.type==="strength_gap"){
   const a=game.away.team_strength_rank,h=game.home.team_strength_rank;
   if(Number.isFinite(Number(a))&&Number.isFinite(Number(h)))return game.away.name+" sits at Team Strength #"+a+" and "+game.home.name+" at #"+h+". This overall quality gap is context, not proof of an advantage in every individual unit.";
   return "There is a gap in overall Team Strength ratings. Check the individual offensive and defensive matchups before treating it as an edge.";
  }
  if(t.type==="game_context"){
   if(game.context?.conference_game)return game.away.name+" and "+game.home.name+" meet in conference play, where familiarity can put greater weight on third-down conversions, turnovers and red-zone execution.";
   if(game.context?.neutral_site)return "With neither team at its usual home stadium, monitor travel, crowd composition and early-game adjustments rather than assuming a standard home-field advantage.";
   return t.detail||"Game location and scheduling provide important context for this matchup.";
  }
  return t.detail||"Review this situational factor alongside the measured team statistics.";
 }
 const row=(game.matchup_metrics||[]).find(m=>m.label===t.metric);
 const away=t.offense_side==="away",off=away?game.away:game.home,def=away?game.home:game.away;
 if(!row)return "The source comparison for "+t.metric+" is unavailable, so no numerical advantage is claimed.";
 const or=away?row.away_offense_rank:row.home_offense_rank,dr=away?row.home_defense_rank:row.away_defense_rank;
 const ov=away?row.away_offense:row.home_offense,dv=away?row.home_defense:row.away_defense;
 const offLabel=row.offense_label||row.label,defLabel=row.defense_label||row.label;
 const value=(v)=>rawVal(v,row.format);
 const offInfo=off.name+" posts "+value(ov)+" "+offLabel.toLowerCase()+" (FBS "+(or==null?"unranked":"#"+or)+")";
 const defInfo=def.name+" allows "+value(dv)+" "+defLabel.toLowerCase()+" (FBS "+(dr==null?"unranked":"#"+dr)+")";
 const explanations={
  "Sack Rate Allowed":["Protection versus pressure","Sack prevention against the opposing pass rush can affect passing efficiency, field position and drive sustainability."],
  "Havoc Allowed":["Disruption and ball security","Tackles for loss, disrupted throws and forced fumbles can derail otherwise efficient possessions."],
  "Turnovers":["Possession leverage","Giveaways against the opposing takeaway ability can swing field position and reduce scoring opportunities."],
  "Success Rate":["Down-to-down efficiency","The better side of this matchup can more consistently win downs and avoid difficult third-down situations."],
  "EPA / Play":["Scoring efficiency per snap","A sustained advantage in per-play scoring value can create separation without requiring explosive gains."],
  "Passing Success Rate":["Passing-down matchup","Efficient throws against this pass defense may determine whether drives continue or stall."],
  "Rushing Success Rate":["Rushing matchup","The run-game efficiency matchup affects manageable distances, play-action options and time of possession."],
  "Explosiveness":["Explosive-play matchup","Chunk plays can shorten drives, while limiting them forces longer, more consistent possessions."],
  "Points per Opportunity":["Scoring-chance conversion","Finishing drives once scoring opportunities develop can separate teams with similar yardage totals."],
  "Third Down Conversion":["Third-down execution","Extending drives against this defense affects possession count, field position and scoring chances."],
  "Red Zone TD Rate":["Red-zone efficiency","Touchdown conversion rather than field goals can have an outsized impact on the final margin."]
 };
 const picked=explanations[t.metric]||["Unit matchup","The difference in these measured units may influence which team controls efficient possessions."];
 const favored=(or!=null&&dr!=null)?(or<dr?off.name:dr<or?def.name:null):null;
 const verdict=favored?" The national ranks favor "+favored+" in this comparison.":" The national ranks suggest a relatively balanced comparison.";
 return offInfo+"; "+defInfo+"."+verdict+" "+picked[1];
}
function factors(){
 const names={"Sack Rate Allowed":"Protection vs. pressure","Havoc Allowed":"Disruption matchup","Turnovers":"Turnover-pressure matchup","Success Rate":"Early-down matchup","EPA / Play":"Per-play efficiency","Passing Success Rate":"Passing-down matchup","Rushing Success Rate":"Rushing matchup","Explosiveness":"Explosive-play matchup","Points per Opportunity":"Scoring-opportunity matchup","Third Down Conversion":"Third-down matchup","Red Zone TD Rate":"Red-zone matchup"};
 const items=(selectedGame.trends||[]).slice(0,8).map(t=>{
  const title=t.type==="matchup_edge"?(names[t.metric]||t.metric):t.type==="bounce_back"?"Response after a loss":t.type==="strength_gap"?"Overall team-strength gap":t.type==="game_context"?"Game setting":t.type==="ranked_context"?"Ranked-team context":"Situational factor";
  const detail=factorSentence(t);
  const label=t.type==="matchup_edge"?"MATCHUP DISCREPANCY":t.type==="bounce_back"?"RECENT FORM":t.type==="strength_gap"?"TEAM STRENGTH":"GAME CONTEXT";
  return '<li><span>'+(t.type==="matchup_edge"?"↗":"!")+'</span><p><small>'+esc(label)+'</small><b>'+esc(title)+'</b><span class="factor-detail">'+esc(detail)+'</span></p></li>';
 }).join("");
 return '<section class="factor-panel"><div class="factor-heading"><div><p class="eyebrow">KEY MATCHUP FACTORS</p><h3>What deserves the closest attention</h3></div><span>Largest matchup discrepancies—not a prediction</span></div><ul>'+items+'</ul></section>';
}


/* Dashboard only: show upcoming matchups, never completed games or past dates. */
function bwTodayET(){const p=Object.fromEntries(new Intl.DateTimeFormat("en-US",{timeZone:"America/New_York",year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+"-"+p.month+"-"+p.day}
function bwUpcoming(g,date){const s=String(g.status||g.state||g.game_status||"").toLowerCase();if(/final|complete|closed|finished|postponed|cancelled|canceled/.test(s))return false;return typeof date==="string"&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&date>=bwTodayET()}
function renderDetail(){
 const g=selectedGame,m=g.market||{},ml=(m.away_moneyline!=null||m.home_moneyline!=null)?`ML ${abbr(g.away)} ${m.away_moneyline??"—"} · ${abbr(g.home)} ${m.home_moneyline??"—"}`:"ML —",markets=[`Spread ${spreadLabel(g)}`,`Total ${m.total??"—"}`,ml,g.weather?.summary||"Weather unavailable"].map(x=>`<span class="pill">${esc(x)}</span>`).join("");
 $("#gameDetail").innerHTML=`<div class="matchup-title"><div><p class="eyebrow">${kickoff(g)}</p><div class="matchup-teams"><span>${mainTeamLogo(g.away)}<b>${esc(g.away.name)}</b></span><i>at</i><span>${mainTeamLogo(g.home)}<b>${esc(g.home.name)}</b></span></div></div><div class="market-strip">${markets}</div></div>
 <section class="season-overview"><p>SEASON SNAPSHOT · COMPLETED GAMES</p><div class="season-overview-grid">${season(g.away,0)}${season(g.home,1)}</div></section>
 <section class="section"><div class="section-head"><div><p class="eyebrow">TRENDS & SITUATIONAL CONTEXT</p><h3>The matchup at a glance</h3></div><span class="subtle">Tap ? for definitions</span></div><div class="trend-groups">${formSchedule()}${BetWiseDashboardUX.byLocation(g,[color(g.away,0),color(g.home,1)])}</div></section>${BetWiseDashboardUX.panel(g)}
<section class="section"><div class="section-head"><div><p class="eyebrow">EFFICIENCY & FBS RANKINGS</p><h3>How the teams compare</h3></div><span class="subtle">FBS ranks · play-mix ranks show frequency</span></div><details class="reading-guide"><summary>How to read these numbers</summary><div><p><b>Season Stat</b> is the current raw season statistic from CollegeFootballData.</p><p><b>FBS Rank</b> is the current-season ordinal national ranking for this exact metric. #1 is best for performance metrics; for Rush/Pass Rate and Rate Against, #1 means the highest frequency. Tied results share a rank.</p><p><b>Each row</b> pairs an offensive metric with its corresponding defensive metric.</p></div></details><div class="metric-columns-head"><span>OFFENSIVE METRICS</span><span>DEFENSIVE METRICS</span></div><div class="grid metric-comparison-grid">${footballMetricCards(g.matchup_metrics||[])}</div></section>
 <section class="section">${feature()}</section>
 
 <section class="section">${factors()}</section>
 <section class="section"><div class="section-head section-head-solo"><div><p class="eyebrow">PLAYER OPPORTUNITY</p></div></div>${playerOpportunity()}</section>`}
function selectGame(id){selectedGame=dashboard.games.find(g=>String(g.game_id)===String(id));document.querySelectorAll(".game-card").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.id===String(id))));$("#gameDetail").hidden=false;renderDetail()}
const dayKey=g=>{if(!g.kickoff)return"tbd";const d=new Date(g.kickoff);return Number.isNaN(d.getTime())?"tbd":(()=>{const p=Object.fromEntries(new Intl.DateTimeFormat("en-US",{year:"numeric",month:"2-digit",day:"2-digit",timeZone:"America/New_York"}).formatToParts(d).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`})()};
function renderGameRail(){
 const q=($("#teamSearch")?.value||"").trim().toLowerCase();const games=dashboard.games.filter(g=>bwUpcoming(g,dayKey(g))&&(activeDay==="all"||dayKey(g)===activeDay)&&(!q||`${g.away.name} ${g.home.name}`.toLowerCase().includes(q)));
 $("#games").innerHTML=games.map(g=>`<button class="game-card" data-id="${g.game_id}" aria-pressed="${selectedGame&&String(selectedGame.game_id)===String(g.game_id)}"><span class="game-time">${kickoff(g)}</span><span class="teams"><span>${teamLogo(g.away,"rail-logo")}<b>${esc(g.away.name)}</b></span><span>${teamLogo(g.home,"rail-logo")}<b>${esc(g.home.name)}</b></span></span><span class="markets"><span>${esc(spreadLabel(g))}</span><span>O/U ${esc(g.market?.total??"—")}</span></span></button>`).join("")||'<p class="empty game-rail-empty">No games scheduled for this day.</p>';
 document.querySelectorAll(".game-card").forEach(b=>b.addEventListener("click",()=>selectGame(b.dataset.id)));
 $("#games").scrollTo({left:0,behavior:"auto"});
}
function renderDayFilters(){
 const days=[...new Set(dashboard.games.filter(g=>bwUpcoming(g,dayKey(g))).map(dayKey))].filter(d=>d!=="tbd").sort();
 $("#dayFilters").innerHTML=[["all","All Games"],...days.map(d=>[d,new Date(d+"T12:00:00Z").toLocaleDateString("en-US",{timeZone:"UTC",weekday:"short",month:"short",day:"numeric"})])].map(([key,label])=>`<button type="button" class="day-filter${activeDay===key?" active":""}" data-day="${esc(key)}" aria-pressed="${activeDay===key}">${esc(label)}</button>`).join("");
 document.querySelectorAll(".day-filter").forEach(b=>b.addEventListener("click",()=>{activeDay=b.dataset.day;renderDayFilters();renderGameRail()}));
 $("#teamSearch").oninput=()=>renderGameRail();
}
function scrollGames(direction){const rail=$("#games");rail.scrollBy({left:direction*Math.max(280,rail.clientWidth*.72),behavior:"smooth"})}
function render(){const d=new Date(dashboard.slate.generated_at);$("#updated").textContent="Updated "+d.toLocaleString("en-US",{month:"short",day:"numeric",year:"numeric",hour:"numeric",minute:"2-digit",timeZone:"America/New_York",timeZoneName:"short"});renderDayFilters();renderGameRail();$("#gamesPrev").onclick=()=>scrollGames(-1);$("#gamesNext").onclick=()=>scrollGames(1);$("#gameDetail").hidden=true}
document.addEventListener("click",e=>{const b=e.target.closest(".info");if(!b||!window.matchMedia("(max-width:760px)").matches)return;e.preventDefault();let d=document.querySelector(".definition-dialog");if(!d){d=document.createElement("dialog");d.className="definition-dialog";d.innerHTML='<div class="definition-dialog-head"><strong></strong><button type="button">✕</button></div><p></p>';d.querySelector("button").onclick=()=>d.close();document.body.appendChild(d)}d.querySelector("strong").textContent=b.getAttribute("aria-label")?.replace(/^About /,"")||"Definition";d.querySelector("p").textContent=b.dataset.tip||"";d.showModal()});
fetch("data/dashboard.json",{cache:"no-store"}).then(r=>{if(!r.ok)throw Error("Dashboard data unavailable");return r.json()}).then(x=>{dashboard=x;render()}).catch(e=>{$("#updated").textContent=e.message});


document.addEventListener("betwise-availability-updated",()=>{if(selectedGame)renderDetail()});
